window.SBL_LESSONS.LT01 = {
  id: 'LT01',
  topicNumber: 1,
  topicTitle: 'Changing leisure patterns',
  title: 'How have leisure patterns changed?',
  href: '/geography/paper-1/option-e/t1-changing/l1-how-have',
  syllabusFocus: 'The growth and changing purpose of leisure time for societies in different geographic and development contexts; categorisation of touristic activities (by cost, duration and destination) and sporting activities (by cost, popularity and site).',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of how leisure patterns have changed' },
    { label: 'Key terms: leisure, recreation, sport, tourism', request: 'Define leisure, recreation, sport and tourism, and explain the differences between them' },
    { label: 'How has leisure time grown?', request: 'Explain how patterns of leisure time have increased in the USA and globally' },
    { label: 'Why has leisure time grown?', request: 'Explain the reasons for the growth in leisure time globally, including technology, affluence and accessibility' },
    { label: 'Categorising touristic activities', request: 'Explain how touristic activities can be categorised by cost, duration and destination' },
    { label: 'Categorising sporting activities', request: 'Explain how sporting activities can be categorised by cost, popularity and site' },
    { label: 'Global differences in leisure time', request: 'Explain why some countries have more leisure time than others' },
    { label: 'The gender gap in leisure time', request: 'Explain the pattern of the gender gap in leisure time seen around the world' }
  ],
  checklist: [
    'I can define the key terms leisure, recreation, sport and tourism.',
    'I can describe how patterns of leisure time have increased in the USA and globally.',
    'I can explain reasons for the growth in leisure time globally, linked to changes in technology, affluence and accessibility.',
    'I can categorise touristic activities by cost, duration and destination.',
    'I can categorise sporting activities by cost, popularity and site.',
    'I can describe global variation in the amount of leisure time people have.',
    'I can describe the pattern of the gender gap in leisure time seen in different countries.'
  ],
  readinessQuestions: [
    'Define leisure and explain how it differs from recreation.',
    'Define sport and tourism, and explain one key difference between them.',
    'Give two reasons for the growth in leisure time globally.',
    'Name one way touristic activities can be categorised, and one way sporting activities can be categorised.',
    'What has happened to the number of hours worked on average in OECD countries over the past 50 years?'
  ],
  quiz: [
    { q: 'Leisure is best defined as:', options: ['Any activity carried out only for payment', 'Any freely chosen activity or experience that takes place in non-work time', 'Only activities that take place at an organised sports club', 'Travel away from home for at least one night'], correct: 1, explain: 'Leisure is any freely chosen activity or experience that takes place in non-work time, once essential and compulsory activities (such as sleeping, working, or essential domestic tasks) have been accounted for.', misconception: 'Leisure is sometimes confused with "free time" in general, including time spent on essential compulsory activities like sleeping; leisure specifically refers to freely chosen activity within that non-work time.', tag: 'Key terms: leisure, recreation, sport, tourism' },
    { q: 'Recreation is best defined as:', options: ['Any travel away from home lasting several nights', 'A leisure-time activity undertaken voluntarily and for enjoyment, including individual pursuits, organised outings/events, and non-paid (non-professional) sport', 'Only professional, competitive sport at an international level', 'Compulsory activity required by an employer'], correct: 1, explain: 'Recreation is a leisure-time activity undertaken voluntarily and for enjoyment, which can include individual pursuits, organised outings and events, and non-paid (non-professional) sport, distinguishing it from professional/competitive sport.', misconception: 'Recreation and sport are sometimes used interchangeably; recreation specifically emphasises voluntary participation for enjoyment, while "sport" (in this syllabus’s definition) implies a more formal, competitive, professional activity.', tag: 'Key terms: leisure, recreation, sport, tourism' },
    { q: 'According to the syllabus definitions used in this course, "sport" refers to:', options: ['Any freely chosen non-work activity of any kind', 'A physical activity involving events and competitions at the national and international scale with professional participants', 'Only activities undertaken purely for relaxation with no competitive element', 'Travel undertaken for at least one night'], correct: 1, explain: 'In this syllabus, sport refers to physical activity involving events and competitions at the national and international scale with professional participants, distinguishing it from the broader, more informal category of recreation.', misconception: 'It might be assumed "sport" and "recreation" mean the same thing; the syllabus’s definitions distinguish sport (formal, competitive, professional) from recreation (voluntary, for enjoyment, often non-professional).', tag: 'Key terms: leisure, recreation, sport, tourism' },
    { q: 'Tourism is defined (for this syllabus) as:', options: ['Any trip away from home, including day trips', 'Travel away from home for at least one night for the purpose of leisure, a definition that excludes day trips', 'Only travel to a different country', 'Any activity undertaken during work hours'], correct: 1, explain: 'Tourism is defined as travel away from home for at least one night for the purpose of leisure; this definition specifically excludes day trips, even though some day trips may be international.', misconception: 'It is sometimes assumed any trip away from home counts as "tourism"; the formal definition used in this syllabus requires at least one overnight stay, which excludes day-trip visitors.', tag: 'Key terms: leisure, recreation, sport, tourism' },
    { q: 'Data on annual hours worked in OECD countries between 1970 and 2006 shows an overall trend of:', options: ['A steady long-term increase in hours worked in almost every country', 'A long-term decline in annual hours worked across most of the selected OECD countries', 'No change at all over the 36-year period', 'Hours worked falling to zero in all countries'], correct: 1, explain: 'OECD data for 1970–2006 shows a long-term decline in annual hours worked across most selected countries (including Canada, France, the UK, Japan, Norway and the USA), which is a key part of the explanation for the growth in leisure time in higher-income countries over this period.', misconception: 'It might be assumed working hours have stayed roughly constant over recent decades; the long-term OECD trend actually shows a substantial decline, particularly pronounced in countries such as France.', tag: 'How has leisure time grown?' },
    { q: 'Which of the following is an example of a "technology" related reason for the growth in leisure time globally?', options: ['Wages increasing overall globally', 'The development and spread of household appliances (such as washing machines and microwaves) reducing the time spent on household chores, leaving more time for leisure', 'An increase in the number of paid holiday days required by law', 'Improved air and land transport making destinations easier to reach'], correct: 1, explain: 'The development and spread of household technology, such as washing machines, microwave ovens and vacuum cleaners, has reduced the time people need to spend on domestic chores, freeing up more time for leisure activities — a technology-related driver of leisure growth.', misconception: 'It is sometimes assumed only "leisure technology" (like smartphones or TVs) explains growth in leisure time; time-saving household technology is just as significant because it directly frees up non-work hours.', tag: 'Why has leisure time grown?' },
    { q: 'Which of the following is an example of an "affluence" related reason for the growth in leisure time globally?', options: ['The introduction of budget airlines and high-speed trains', 'Increased advertisement and the internet making it easier for people to know where they can visit for leisure and tourism', 'Overall wage increases giving people more disposable income to spend on leisure activities and holidays', 'The spread of social media promoting new sports and leisure activities'], correct: 2, explain: 'Rising wages and disposable income (affluence) is a major driver of leisure growth, giving more people the financial means to spend on leisure activities and holidays; this is distinct from technology-related drivers (such as household appliances) and accessibility-related drivers (such as transport improvements).', misconception: 'The categories of technology, affluence and accessibility can overlap and are sometimes confused; affluence specifically refers to increased income/wealth enabling greater leisure spending, rather than the technology or infrastructure that enables access.', tag: 'Why has leisure time grown?' },
    { q: 'Which of the following is an example of an "accessibility" related reason for the growth in leisure time globally?', options: ['Wages increasing overall globally, giving people more disposable income', 'Rising life expectancy meaning more people live well past retirement age', 'Improved air, sea and land transport, including budget airlines and high-speed trains, making it easier and quicker to reach tourism and leisure destinations', 'Improvements in household appliances reducing time spent on domestic chores'], correct: 2, explain: 'Improved transport infrastructure and options, such as budget airlines and high-speed trains (e.g. the Eurostar), have made it easier, faster and often cheaper for people to reach tourism and leisure destinations, an accessibility-related driver of leisure growth.', misconception: 'Accessibility is sometimes assumed to only refer to legal/political access (like passport rules); in this context, it specifically refers to how physically easy and affordable it is to travel to a destination.', tag: 'Why has leisure time grown?' },
    { q: 'Touristic activities can be categorised in several ways, including by:', options: ['Cost, duration and destination', 'Only by the exact date they take place', 'Only by the number of participants involved', 'Only by whether they occur indoors or outdoors'], correct: 0, explain: 'Touristic activities are commonly categorised by cost (e.g. budget vs luxury), duration (e.g. day trip, short break, long-haul holiday) and destination (e.g. domestic vs international, urban vs rural, coastal vs inland).', misconception: 'It might be assumed there is only one way to classify touristic activities; using multiple categorisation criteria (cost, duration, destination) allows for a much more nuanced comparison between different types of tourism.', tag: 'Categorising touristic activities' },
    { q: 'Sporting activities can be categorised in several ways, including by:', options: ['Cost, popularity and site (the location/facility required)', 'Only by the country in which they originated', 'Only by whether professional athletes are involved', 'Only by the colour of the equipment used'], correct: 0, explain: 'Sporting activities are commonly categorised by cost (e.g. low-cost activities like running vs high-cost activities like golf or skiing), popularity (mass-participation sports vs niche sports) and site (the type of location or facility required, such as a specific pitch, court, mountain or body of water).', misconception: 'Sporting activities are sometimes only thought of in terms of their popularity; cost and the specific site/facility required are equally important factors affecting who can realistically participate.', tag: 'Categorising sporting activities' }
  ]
};

window.SBL_LESSONS.LT02 = {
  id: 'LT02',
  topicNumber: 1,
  topicTitle: 'Changing leisure patterns',
  title: 'What is the link between economic development and leisure?',
  href: '/geography/paper-1/option-e/t1-changing/l2-what-is-the',
  syllabusFocus: 'The link between economic development and participation in leisure activities; detailed examples to illustrate recent changes in participation for two or more societies at contrasting levels of development, including barriers to participation in low-income countries and for low-income groups within higher- and middle-income countries.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of the link between economic development and leisure time' },
    { label: 'Income and leisure trade-off', request: 'Explain the trade-off between income and leisure time shown on an indifference curve graph' },
    { label: 'Barriers to participation in LICs', request: 'Explain the barriers to participation in leisure activities in low-income countries' },
    { label: 'Barriers for low-income groups in HICs/MICs', request: 'Explain the barriers to participation in leisure activities for low-income groups within higher- and middle-income countries' },
    { label: 'Case study: leisure in China', request: 'Explain how China’s rapid economic development has changed participation in leisure and tourism' },
    { label: 'Case study: leisure in the USA', request: 'Explain patterns of leisure participation in the USA despite its high level of economic development' },
    { label: 'Comparing China and the USA', request: 'Compare how economic development has affected leisure participation differently in China and the USA' },
    { label: 'The gender gap in leisure and development', request: 'Explain how the gender gap in leisure time relates to a country’s level of economic development' }
  ],
  checklist: [
    'I can describe the correlation between increased income and leisure time.',
    'I can explain the trade-off between income and leisure time shown on an indifference curve graph.',
    'I can explain barriers to participation in leisure activities in low-income countries.',
    'I can explain barriers to participation for low-income groups within higher- and middle-income countries.',
    'I can describe and explain recent changes in leisure/tourism participation in China, linked to its economic development.',
    'I can describe and explain patterns of leisure participation in the USA, including the "vacation deprivation" phenomenon.',
    'I can compare how economic development has shaped leisure participation differently in China and the USA.'
  ],
  readinessQuestions: [
    'Describe the general relationship between income and leisure time.',
    'Give two barriers to participation in leisure activities in low-income countries.',
    'Give one barrier to participation in leisure activities for low-income groups within a higher-income country.',
    'Outline one way in which China’s economic development has changed leisure/tourism participation.',
    'Outline one way in which leisure participation in the USA shows that high income does not always mean high leisure time.'
  ],
  quiz: [
    { q: 'In general, as a country’s level of economic development increases, its population’s participation in leisure activities tends to:', options: ['Decrease consistently to zero', 'Increase, as rising incomes give people more disposable income and, often, more free time to spend on leisure', 'Stay completely unrelated to income at all times', 'Only ever affect the number of professional athletes'], correct: 1, explain: 'In general, higher levels of economic development are associated with increased participation in leisure activities, as rising incomes give people more disposable income to spend on leisure and tourism, and rising living standards are often (though not always) accompanied by more available free time.', misconception: 'The relationship between development and leisure participation is sometimes assumed to be simple and automatic; the USA case study shows that high income does not automatically translate into more leisure time actually taken, due to work culture factors.', tag: 'Income and leisure trade-off' },
    { q: 'On an income-leisure trade-off (indifference curve) graph, a movement from a point with more leisure and less income to a point with more income and less leisure represents:', options: ['A person choosing to work more hours in exchange for higher earnings, giving up some leisure time to do so', 'A country experiencing a natural disaster', 'A permanent, irreversible loss of all leisure time', 'A decrease in a person’s overall standard of living'], correct: 0, explain: 'An income-leisure trade-off graph illustrates how individuals must choose between working more hours (more income, less leisure time) or working fewer hours (more leisure time, less income), with indifference curves representing combinations of income and leisure that provide the same level of satisfaction (utility) to that person.', misconception: 'This trade-off is sometimes assumed to only apply to poorer individuals; in economics, the income-leisure trade-off is a general concept that applies to decision-making about working hours at any income level.', tag: 'Income and leisure trade-off' },
    { q: 'A key barrier to participation in leisure activities in low-income countries (LICs) is:', options: ['An oversupply of free leisure facilities', 'Low disposable income and a greater share of time needed for work and essential survival activities, leaving little time or money for leisure', 'Too much paid holiday leave being offered to workers', 'A complete absence of any leisure activities anywhere in LICs'], correct: 1, explain: 'In many LICs, low disposable income and the need to spend a greater proportion of time on work and essential survival activities (such as subsistence agriculture or informal work) leaves less time and money available for leisure, alongside often limited leisure infrastructure.', misconception: 'It might be assumed leisure barriers are only about a lack of facilities; a lack of disposable income and, crucially, a lack of free time due to work demands are just as significant.', tag: 'Barriers to participation in LICs' },
    { q: 'Which of the following is a barrier to leisure participation faced specifically by low-income groups within higher-income countries (HICs)?', options: ['A complete absence of any leisure facilities in HICs', 'The relatively high cost of leisure centre and sports facility membership/fees, which can be unaffordable on a low income even within a wealthy country', 'Low-income groups in HICs having too much free time', 'A ban on leisure activities for low-income groups'], correct: 1, explain: 'Even within wealthy countries, low-income groups can face significant barriers to leisure participation, including the relatively high cost of facility membership and fees, poor local area conditions discouraging outdoor activity, and a lack of free time due to long working hours or multiple jobs.', misconception: 'It is sometimes assumed that living in a high-income country guarantees access to leisure; income inequality within HICs means some groups face very similar barriers (cost, time, safety) to those seen in lower-income countries.', tag: 'Barriers for low-income groups in HICs/MICs' },
    { q: 'China’s rapid economic development over the past two decades has been associated with:', options: ['A decline in tourism of all kinds', 'Explosive growth in domestic tourism (now the world’s largest domestic tourism market) and rapid growth in outbound international tourism, driven by a rapidly expanding middle class', 'No change in leisure or tourism participation at all', 'The complete banning of tourism by the government'], correct: 1, explain: 'China’s rapid economic development has been associated with explosive growth in leisure and tourism participation: domestic tourism has grown to become the world’s largest domestic market (billions of trips per year), and outbound international tourism has also grown rapidly, driven by a rapidly expanding middle class with rising disposable income, supported by government-mandated holiday periods such as "Golden Week".', misconception: 'It might be assumed a country’s tourism industry grows only slowly and steadily; China’s case shows how rapid economic development can produce very fast, large-scale growth in both domestic and outbound leisure/tourism participation.', tag: 'Case study: leisure in China' },
    { q: 'Despite being one of the world’s wealthiest countries, the USA shows a notable pattern in which:', options: ['Workers receive more paid vacation days than any other country in the world', 'Workers receive comparatively few paid vacation days (commonly cited as around 12 days a year, the fewest among countries surveyed), and a significant proportion do not use all the leave they are entitled to', 'All workers are legally guaranteed at least six weeks of paid leave', 'Leisure time has grown faster in the USA than in any other country'], correct: 1, explain: 'The USA is notable for offering comparatively few paid vacation days (commonly cited as around 12 days a year in international comparisons, the fewest among countries surveyed by organisations such as Expedia), and many US workers do not use all of the paid leave they are entitled to, a pattern sometimes called "vacation deprivation".', misconception: 'It is sometimes assumed a country’s wealth automatically leads to generous leisure time for its workers; the USA demonstrates that a country can be highly economically developed while its work culture still limits how much leisure time people actually take.', tag: 'Case study: leisure in the USA' },
    { q: 'Comparing China and the USA illustrates an important geographical idea, that:', options: ['Economic development always produces exactly the same leisure participation outcomes in every country', 'Economic development can shape leisure participation very differently depending on a country’s culture, government policy and work practices, rather than income alone determining outcomes', 'Only low-income countries show any variation in leisure patterns', 'Leisure participation is entirely unrelated to any economic factor'], correct: 1, explain: 'Comparing China (where rapid income growth has driven an explosive rise in leisure and tourism participation) with the USA (where very high income has not translated into correspondingly high uptake of leisure time, due to work culture and vacation policy) shows that economic development alone does not determine leisure outcomes; culture, government policy and workplace norms also play a major role.', misconception: 'It might be assumed higher GDP automatically means more leisure time for a population; the USA/China comparison is a strong example of how the same broad trend (rising development) can produce very different leisure outcomes depending on other factors.', tag: 'Comparing China and the USA' },
    { q: 'Data on the gender gap in leisure time (2020) shows that, in most countries surveyed:', options: ['Men and women have exactly equal amounts of leisure time everywhere', 'Women tend to have less average daily leisure time than men, with the gap varying significantly between countries', 'Women consistently have significantly more leisure time than men in every country', 'Leisure time is unrelated to gender in any country'], correct: 1, explain: 'Global data on the gender gap in leisure time shows that in most countries surveyed, women tend to have less average daily leisure time than men (often linked to women undertaking a larger share of unpaid domestic and caregiving work), although the size of this gap varies significantly between countries.', misconception: 'It might be assumed gender differences in leisure time are the same everywhere or have disappeared in wealthier countries; the pattern (and its size) varies considerably between countries and is not simply explained by a country’s income level alone.', tag: 'The gender gap in leisure and development' },
    { q: 'China’s government-mandated "Golden Week" holiday periods are significant for leisure geography because they:', options: ['Ban all travel during those weeks', 'Concentrate enormous surges in domestic and outbound travel into short periods, driving major "new consumption trends" in tourism and leisure spending', 'Have no effect on tourism patterns at all', 'Only apply to international tourists visiting China'], correct: 1, explain: 'China’s government-mandated Golden Week holidays (such as around National Day and Spring Festival) concentrate huge surges in domestic and outbound travel into short periods, which are explicitly linked to major "new consumption trends" in tourism and leisure spending as China’s middle class has grown.', misconception: 'Government holiday policy is sometimes overlooked as a factor shaping leisure geography; in China’s case, a specific policy decision has a measurable, large-scale effect on national travel patterns.', tag: 'Case study: leisure in China' },
    { q: 'The gap between the USA’s average paid vacation allowance and a country such as France (which offers around 29 days) illustrates that:', options: ['All high-income countries offer identical amounts of paid leave', 'Government policy and cultural attitudes towards vacation time can differ substantially even between wealthy, highly developed countries', 'France has a much lower level of economic development than the USA', 'Vacation entitlement is set by an international law that applies equally to all countries'], correct: 1, explain: 'The USA’s comparatively low paid vacation allowance (around 12 days) contrasts sharply with countries such as France (around 29 days, where the vast majority of workers treat vacation as a fundamental right), showing that government policy and cultural attitudes towards leisure time can differ substantially between countries at similarly high levels of economic development.', misconception: 'It might be assumed vacation entitlement is set by some universal standard; in reality, it is determined by each country’s own labour laws and cultural norms, which vary widely even among wealthy nations.', tag: 'Case study: leisure in the USA' }
  ]
};

